	//    {
	//        "instrument_name":"LTC_USDT",
	//        "subscription":"book.LTC_USDT.150",
	//        "channel":"book",
	//        "depth":150,
	//        "data": [
	//             {
	//                 "bids": [
	//                     [122.21, 0.74041, 4]
	//                 ],
	//                 "asks": [
	//                     [122.29, 0.00002, 1]
	//                 ]
	//                 "t": 1648123943803,
	//                 "s":754560122
	//             }
	//         ]
	//    }
	//  update
	//    {
	//        "instrument_name":"BTC_USDT",
	//        "subscription":"book.BTC_USDT.50",
	//        "channel":"book.update",
	//        "depth":50,
	//        "data":[
	//           {
	//              "update":{
	//                 "asks":[
	//                    [
	//                       "43755.46",
	//                       "0.10000",
	//                       "1"
	//                    ],
	//                    ...
	//                 ],
	//                 "bids":[
	//                    [
	//                       "43737.46",
	//                       "0.14096",
	//                       "1"
	//                    ],
	//                    ...
	//                 ]
	//              },
	//              "t":1704484068898,
	//              "tt":1704484068892,
	//              "u":78795598253024,
	//              "pu":78795598162080,
	//              "cs":-781431132
	//           }
	//        ]
	//    }
	//
	var marketId *string = this.SafeString(message, "instrument_name")
	var market map[string]any = ccxt.MapTyped(this.SafeMarket(marketId))
	var symbol any = market["symbol"]
	var data any = this.SafeValue(message, "data")
