func (this *Cryptocom) HandleErrorMessage(client any, message any) any {
	//
	//    {
	//        "id": 0,
	//        "code": 10004,
	//        "method": "subscribe",
	//        "message": "invalid channel {"channels":["trade.BTCUSD-PERP"]}"
	//    }
	//
	var id *string = this.SafeString(message, "id")
	var errorCode *string = this.SafeString(message, "code")

	{
		ret__ := func(this *Cryptocom) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Cryptocom) any {
						// catch block:
						if ccxt.IsInstance(e, ccxt.AuthenticationError) {
							var messageHash string = "authenticated"
							client.(ccxt.ClientInterface).Reject(e, messageHash)
							if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash) {
								ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
							}
						} else {
							client.(ccxt.ClientInterface).Reject(e, id)
						}
						return true

					}(this)
				}
			}()
			// try block:
			if ((errorCode != nil) && (errorCode == nil || *errorCode != "")) && (errorCode == nil || *errorCode != "0") {
				var feedback any = ccxt.Add(this.Id+" ", this.Json(message))
				this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
				var messageString *string = this.SafeString(message, "message")
				if messageString != nil {
					this.ThrowBroadlyMatchedException(this.Exceptions["broad"], messageString, feedback)
				}
				panic(ccxt.ExchangeError(feedback))
			}
			return false

		}(this)
		if ret__ != nil {
			return ret__
		}
		return nil
	}
}
func (this *Cryptocom) HandleSubscribe(client any, message map[string]any) {
	var methods map[string]any = map[string]any{
		"candlestick":           this.HandleOHLCV,
		"ticker":                this.HandleTicker,
		"trade":                 this.HandleTrades,
		"book":                  this.HandleOrderBook,
		"book.update":           this.HandleOrderBook,
		"user.order":            this.HandleOrders,
		"user.trade":            this.HandleTrades,
		"user.balance":          this.HandleBalance,
		"user.position_balance": this.HandlePositions,
	}
	var result any = this.SafeValue2(message, "result", "info")
	var channel *string = this.SafeString(result, "channel")
	if (channel != nil) && (func() int {
		if channel == nil {
			return -1
		}
		return strings.Index(*channel, "user.trade")
	}() > -1) {
		// channel might be user.trade.BTC_USDT
		this.HandleTrades(client, result)
	}
	if (channel != nil) && ccxt.StartsWith(channel, "user.order") {
		// channel might be user.order.BTC_USDT
		this.HandleOrders(client, result)
	}
	var method any = this.SafeValue(methods, channel)
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, result)
	}
}
func (this *Cryptocom) HandleMessage(client any, message any) {
	//
	// ping
	//    {
	//        "id": 1587523073344,
	//        "method": "public/heartbeat",
	//        "code": 0
	//    }
	// auth
	//     { id: 1648132625434, method: "public/auth", code: 0 }
	// ohlcv
	//    {
	//        "code": 0,
	//        "method": "subscribe",
	//        "result": {
	//          "instrument_name": "BTC_USDT",
	//          "subscription": "candlestick.1m.BTC_USDT",
	//          "channel": "candlestick",
	//          "depth": 300,
	//          "interval": "1m",
	//          "data": [ [Object] ]
	//        }
	//      }
	// ticker
	//    {
	//        "info":{
	//           "instrument_name":"BTC_USDT",
	//           "subscription":"ticker.BTC_USDT",
	//           "channel":"ticker",
	//           "data":[ { } ]
	//
	// handle unsubscribe
	// {"id":1725448572836,"method":"unsubscribe","code":0}
	//
	if ccxt.IsEqual(this.HandleErrorMessage(client, message), true) {
		return
	}
	var method *string = this.SafeString(message, "method")
	var methods map[string]any = map[string]any{
		"":                          this.HandlePing,
		"public/heartbeat":          this.HandlePing,
		"public/auth":               this.HandleAuthenticate,
		"private/create-order":      this.HandleOrder,
		"private/amend-order":       this.HandleOrder,
		"private/cancel-order":      this.HandleOrder,
		"private/cancel-all-orders": this.HandleCancelAllOrders,
		"private/close-position":    this.HandleOrder,
		"subscribe":                 this.HandleSubscribe,
		"unsubscribe":               this.HandleUnsubscribe,
	}
	var callMethod any = this.SafeValue(methods, method)
	if !ccxt.IsEqual(callMethod, nil) {
		ccxt.CallDynamically(callMethod, client, message)
	}
}
func (this *Cryptocom) AuthenticateAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Cryptocom) authenticateBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "private")
	var client ccxt.ClientInterface = this.Client(url)
	var messageHash string = "authenticated"
	var future any = client.(ccxt.ClientInterface).ReusableFuture(messageHash)
	var authenticated any = this.SafeValue(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
	if ccxt.IsEqual(authenticated, nil) {
		var method string = "public/auth"
		var nonce string = ccxt.ToString(this.Nonce())
		var auth any = ccxt.Add(ccxt.Add(method+nonce, this.ApiKey), nonce)
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), ccxt.Sha256)
		var request map[string]any = map[string]any{
			"id":      nonce,
			"nonce":   nonce,
			"method":  method,
			"api_key": this.ApiKey,
			"sig":     signature,
		}
		var message map[string]any = this.Extend(request, params)
		this.Watch(url, messageHash, message, messageHash)
	}

	ch <- ccxt.PanicOnError(<-future.(*ccxt.Future).Await())
	return nil
}
func (this *Cryptocom) HandlePing(client any, message map[string]any) {
	this.Spawn(this.PongAsync, client, message)
}
func (this *Cryptocom) HandleAuthenticate(client any, message map[string]any) {
	//
	//  { id: 1648132625434, method: "public/auth", code: 0 }
	//
	var future any = this.SafeValue(client.(ccxt.ClientInterface).GetFutures(), "authenticated")
	future.(*ccxt.Future).Resolve(true)
}
func (this *Cryptocom) HandleUnsubscribe(client any, message map[string]any) {
	var id *string = this.SafeString(message, "id")
	var keys []string = ccxt.ObjectKeys(client.(ccxt.ClientInterface).GetSubscriptions())
	for i := 0; i < len(keys); i++ {
		var messageHash string = ccxt.GetValue(keys, i).(string)
		if !(ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)) {
			continue
		}
		if strings.HasPrefix(messageHash, "unsubscribe") {
			var subscription any = ccxt.GetValue(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
			var subId *string = this.SafeString(subscription, "id")
			if id != subId && (id == nil || subId == nil || *id != *subId) {
				continue
			}
			var messageHashes []any = ccxt.SafeListTyped(subscription, "messageHashes")
			var subMessageHashes []any = ccxt.SafeListTyped(subscription, "subMessageHashes")
			for j := 0; j < len(messageHashes); j++ {
				var unsubHash any = func() any {
					if j >= 0 && j < len(messageHashes) {
						return ccxt.DerefScalar(messageHashes[j])
					}
					return nil
				}()
				var subHash any = func() any {
					if j >= 0 && j < len(subMessageHashes) {
						return ccxt.DerefScalar(subMessageHashes[j])
					}
					return nil
				}()
				this.CleanUnsubscription(ccxt.AsClient(client), subHash, unsubHash)
			}
			this.CleanCache(subscription)
		}
	}
}

